package dev.gbppimentel.zzz;
import java.nio.file.*;import java.io.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;import org.json.*;
public final class ContextParserTest{public static void main(String[] args)throws Exception{int n=0;String text=Files.readString(Path.of("assets/combat-catalog.json"));ContextParser p=new ContextParser(text);if(!ContextParser.uid("UID: 1000000001 11").equals("1000000001"))throw new AssertionError("UID parse");n++;if(!ContextParser.uid("13004362 04").isEmpty())throw new AssertionError("Broken UID cannot verify account");n++;ContextParser.Identity id=new ContextParser.Identity();if(id.update("1000000001"))throw new AssertionError("One frame cannot open account");n++;if(!id.update("1000000001"))throw new AssertionError("Stable UID must open account");n++;id.update("1000000000");if(!id.confirmed.equals("1000000001"))throw new AssertionError("One OCR mistake must preserve verified identity");id.update("1000000000");id.update("1000000000");if(!id.confirmed.equals("1000000000"))throw new AssertionError("Repeated account change must replace verification");n++;for(int i=0;i<50;i++)id.update("");if(!id.confirmed.equals("1000000000"))throw new AssertionError("Hidden UID cannot expire a verified game session");n++;id.clear();if(!id.candidate.isEmpty()||!id.confirmed.isEmpty())throw new AssertionError("Game close must reset identity");n++;if(p.enemy("random letters from UI")!=null)throw new AssertionError("Unmatched enemy must stay unknown");n++;if(!p.agent("Phoenix Command List").equals("1641"))throw new AssertionError("Agent text parse");n++;
if(!ContextParser.consistentUid("1000000001","D:100000000111").equals("1000000001"))throw new AssertionError("Adjacent signal bars must not prevent a clean numeral-strip reading");n++;
if(!ContextParser.consistentUid("","UID: 1000000001").equals("1000000001"))throw new AssertionError("Legacy crop remains usable");n++;
if(!ContextParser.consistentUid("1000000001","1000000000").isEmpty())throw new AssertionError("Conflicting valid readings must remain unknown");n++;
if(!ContextParser.consistentUid("100000000111","10000000 01").isEmpty())throw new AssertionError("Never trim or join broken UID digits");n++;
if(!ContextParser.uidCrops("UID:1000000001","1000000001","100000001","100000001").equals("1000000001"))throw new AssertionError("Complete fields outrank truncated numeral crops");n++;
if(!ContextParser.uidCrops("1000000001","1000000000","1000000001","1000000001").isEmpty())throw new AssertionError("Conflicting complete fields cannot be overridden");n++;
if(!ContextParser.uidCrops("","","1000000001","1000000001").equals("1000000001"))throw new AssertionError("Bright-background numeral pair must agree");n++;
if(!ContextParser.uidCrops("","","1000000001","1000000000").isEmpty())throw new AssertionError("Conflicting numeral crops remain unknown");n++;
if(!ContextParser.uidCrops("1000000001","","","").equals("1000000001"))throw new AssertionError("Empty crops do not discard a complete readable field");n++;
if(!ContextParser.uidCrops("","","1000000001","").equals("1000000001"))throw new AssertionError("Readable numeral fallback still requires temporal identity confirmation");n++;
System.out.println(n+" context policy checks passed");}}
